  const chars = Array.from(s);
  const offsets = [0];
  for (const c of chars) {
    offsets.push(offsets[offsets.length - 1] + c.length);
  }

  let left = 0;
  let bestStart = 0;
  let bestLength = Infinity;

  for (let right = 0; right < chars.length; right++) {
    const c = chars[right];
    if (need.has(c)) {
      const count = need.get(c);
      if (count > 0) missing--;
      need.set(c, count - 1);
    }

    while (missing === 0) {
      const length = offsets[right + 1] - offsets[left];
      if (length < bestLength) {
        bestStart = offsets[left];
        bestLength = length;
      }

      const removed = chars[left++];
      if (need.has(removed)) {
        const count = need.get(removed) + 1;
        need.set(removed, count);
        if (count > 0) missing++;
      }
    }
  }

  return bestLength === Infinity
